    CLOUD_R4BO9_CUS = "CLOUD_R4BO9_CUS"
    CLOUD_R4BN9_CUS = "CLOUD_R4BN9_CUS"
    CLOUD_R4E12_CUS = "CLOUD_R4E12_CUS"
    CLOUD_R4LANO_CUS = "CLOUD_R4LANO_CUS"
    CLOUD_R4BANO_CUS = "CLOUD_R4BANO_CUS"
    CLOUD_R4LP12_CUS = "CLOUD_R4LP12_CUS"
    CLOUD_R4LAPO_CUS = "CLOUD_R4LAPO_CUS"
    CLOUD_R4MANO_CUS = "CLOUD_R4MANO_CUS"
    CLOUD_R4MAPN_CUS = "CLOUD_R4MAPN_CUS"
    CLOUD_R4LO9_CUS = "CLOUD_R4LO9_CUS"

    def __str__(self):
        return " {} ".format(self.name)

    def __repr__(self):
        return str(self)

    @staticmethod
    def argparse(s):
        try:
            return Topologies[s.upper()]
        except KeyError:
            return s


