def open_xml(xml_path, get_first_child=True, print_info=False):
    xml_file = open(xml_path)
    xml_string = xml_file.read()
    xml_file.close()

    # remove namespace
    xml_string = re.sub(' xmlns="[^"]+"', '', xml_string, count=1)
    tree = ElementTree(xml.etree.ElementTree.fromstring(xml_string))

    root = tree.getroot()
    if print_info:
        print()
        print("-----------------------------------------------")
        print("Read commissioning from file:", xml_path)

    if get_first_child:
        return root[0]
    else:
        return root


def get_arguments():
    parser = argparse.ArgumentParser()
    parser.add_argument('-i', '--input', type=str, required=True, help="Input file")
    parser.add_argument('-o', '--output', type=str, required=False, help="Output file")
    parser.add_argument('-t', '--topology', type=Topologies.argparse,
                        choices=list(Topologies), required=False, help="Topology")

    args = parser.parse_args()

    if args.input is not None and not path.exists(args.input):
        print(args.input, " not exist")
        raise Exception("File ", args.input, " not exist")

    return args


def save_xml(xml_save_path, cm_data):
    root = Element("raml", attrib={"version": "2.1"})
    root.append(cm_data)
    tree = ElementTree(root)
    if sys.version_info.major >= 3 and sys.version_info.minor >= 9:
        xml.etree.ElementTree.indent(tree)  # available since python3.9
    tree.write(xml_save_path, encoding="utf-8", xml_declaration=True)
    print("Saving new commission in", xml_save_path)
    print("-----------------------------------------------")
    print()


def get_xml_p(name, value):
    p = Element("p")
    p.set("name", name)
    p.text = value
    return p


def remove_parameter(object_element, object_name, parameter_name):
    parameter = object_element.find("p[@name='{}']".format(parameter_name))
    if parameter is not None:
        object_element.remove(parameter)
        print("--> Removing {} {}".format(object_name, parameter_name))


def change_parameter(object_element, object_name, parameter_name, value, override=True):
    parameter = object_element.find("p[@name='{}']".format(parameter_name))
    if parameter is None:
        object_element.append(get_xml_p(parameter_name, value))
        print("--> Adding {} {} = {}".format(object_name, parameter_name, value))
    elif parameter.text != value:
        if override:
            parameter.text = value
            print("--> Changing {} {} to {}".format(object_name, parameter_name, value))


def get_product_code(element: Element, object_name):
    product_code = element.find("p[@name='prodCodePlanned']")
    if product_code is None:
        raise Exception("Product code for {} not found".format(object_name))

    product_code = product_code.text
    if product_code.find(".") != -1:
        product_code = product_code[:product_code.find(".")]

    return product_code


def get_smod_object(commission: Element):
    # More than 1 SMOD means full rack which is not supported on CLOUD
    smod_obj = commission.findall(XMLObjectNames.SMOD)
    if smod_obj is None:
        raise Exception("No CABINET object detected")
    elif len(smod_obj) > 1:
        raise Exception("There could be only one SMOD object - FullRack is not supported")
    else:
        smod_object = smod_obj[0]

    return smod_object


def prettify_cus_ini(cus_ini):
    max_len = 0
    for line in cus_ini.split("\n"):
        prop = line.split("=")
        if len(prop) >= 2:
            max_len = max(max_len, len(prop[0].strip()))

    pretty_ini = ""
    for line in cus_ini.split("\n"):
        prop = line.split("=")
        if len(prop) == 2:
            pretty_ini += prop[0].strip().ljust(max_len)
            pretty_ini += " = {}".format(prop[1].strip()) + NL
        else:
            pretty_ini += line + NL
    return pretty_ini
